using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;using ReplierDesktop;
public static class SceneTieChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 [STAThread] public static int Main(string[] a){try{var json=new JavaScriptSerializer();var material=json.Serialize(new{context_version=2,scene=new SceneReading{Topic="장비",Situation="큰 비용",Outcome="좋은 결과와 아쉬움",Nuance="복잡한 마음",Angles=new[]{"과정","결과","감상"},EvidenceIds=new[]{"c0"}}});var video=new Video{Id="V0000000001",Title="장비에 쓴 비용"};var rows=Enumerable.Range(0,3).Select(i=>new CommentSuggestion{Text="동점 후보 "+i,FitScore=87,FitEligible=true,Material=material,FitReason="기본 평가",Evidence="UI 검사 대사"}).ToList();rows.Add(new CommentSuggestion{Text="제외된 백점 후보",FitScore=100,FitEligible=false});int calls=0;
 var compare=new SceneTieBreaker((name,body,t)=>{calls++;var request=SceneMaterial.Json(json.Serialize(body));var messages=(object[])CaptionService.Get(request,"messages");string input=(string)CaptionService.Get(messages.Last(),"content");Check(CaptionService.Get(SceneMaterial.Json(input),"title")==null&&CaptionService.Get(SceneMaterial.Json(input),"situation")==null,"equal-score fluency comparison sees candidate sentences without video anchoring");Check(!input.Contains("제외된 백점"),"rejected candidate cannot enter direct comparison");return Task.FromResult(json.Serialize(new{choice=calls==1?0:calls==2?2:1}));},name=>Task.FromResult(0));compare.Apply(video,rows,CancellationToken.None).GetAwaiter().GetResult();Check(calls==3&&rows[2].TiePreference==2&&rows.Take(2).All(c=>c.TiePreference==0),"disagreement is resolved by comparing only the two preferred candidates");Check(rows.Take(3).All(c=>c.FitScore==87),"direct preference never inflates numerical suitability scores");
 using(var form=new MainForm(Path.Combine(a[0],"history.json"))){form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();var result=new DualCommentResult{Complete=true,Batches=new List<ModelCommentBatch>{new ModelCommentBatch{Label="G",Result=new CommentResult{Comments=rows,QualityFiltered=true}},new ModelCommentBatch{Label="Q",Result=new CommentResult{Comments=new List<CommentSuggestion>{new CommentSuggestion{Text="낮은 점수",Evidence="UI 검사 대사",FitScore=86,FitEligible=true,TiePreference=99}},QualityFiltered=true}}}};typeof(MainForm).GetMethod("RenderComments",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{result});var grid=(DataGridView)form.Controls.Find("Comments",true)[0];Check(object.ReferenceEquals(grid.Rows[0].Tag,rows[2]),"UI uses direct preference only within the numerical highest-score tie");Check(grid.Rows[0].Cells["fit"].ToolTipText.Contains("직접 비교"),"selection reason explains comparison rather than claiming generation-order tie breaking");}
 foreach(var row in rows){row.TiePreference=0;row.TieReason=null;}calls=0;var failed=new SceneTieBreaker((name,body,t)=>{calls++;if(calls==1)return Task.FromResult("{\"choice\":2}");var task=new TaskCompletionSource<string>();task.SetException(new InvalidDataException("검사용 비교 실패"));return task.Task;},name=>Task.FromResult(0));bool rejected=false;try{failed.Apply(video,rows,CancellationToken.None).GetAwaiter().GetResult();}catch(InvalidDataException){rejected=true;}Check(rejected&&rows.All(c=>c.TiePreference==0),"partial judge failure cannot publish a one-sided preference");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
